#!/usr/bin/env bash
# =============================================================================
# Create GitHub issues — <feature title>
#
# Generated by the Task Splitter agent from brainstorming/<feature>/:
#   user-stories.md, tech-design.md, implementation-plan.md (or task-splitting.md)
#
# Usage:
#   ./create-issues.sh              # dry run: prints every issue, changes nothing
#   ./create-issues.sh --execute    # creates or updates the issues on GitHub
#
# Re-runnable: an issue is matched by its exact title and updated in place.
# Sub-issue links are only added when missing, and project fields are only set
# when empty: a re-run completes an interrupted run, and never resets a status
# the team has moved since.
#
# Prerequisites:
#   - gh CLI, authenticated with the project scope: gh auth refresh -s project
#   - jq
#
# Runs in bash on macOS, Linux and Windows (Git Bash or WSL; from PowerShell,
# prefix it with bash).
# =============================================================================

# POSIX syntax on purpose: sh (dash on Ubuntu) and zsh reach this line before failing on bash syntax.
if [ -z "${BASH_VERSION:-}" ]; then
  echo "Run this script with bash: ./create-issues.sh or bash create-issues.sh" >&2
  exit 1
fi

set -euo pipefail

# A native jq.exe called from Git Bash on Windows ends its lines with CRLF: drop the CR, or every
# id read through jq carries it into the next gh call.
jq() { command jq "$@" | tr -d '\r'; }

OWNER="OpenAEV-Platform"
REPO_NAME="openaev"
REPO="${OWNER}/${REPO_NAME}"
PROJECT_NUMBER="2" # OpenAEV - Product Backlog
PROJECT_STATUS="Tech refinement"
ISSUE_TYPE="Feature"
EPIC_LABELS="feature,epic"
TASK_LABELS="feature"

# --- Feature (filled in by the Task Splitter) --------------------------------
TOPIC="<topic>"                        # one word: audit-log, multitenancy, ...
FEATURE_TITLE="<feature title>"
TECH_DESIGN_PATH="brainstorming/<feature>/tech-design.md"  # path in the repository
USER_STORIES_URL="<Notion user stories page, or empty>"
VERTICALE="<1, 2 or 3>"                # the vertical the requester chose, see below
FEATURE_FLAG="<true or false>"         # true when the feature ships behind a feature flag

# A value still shaped like the template's "<...>" was never filled in.
PLACEHOLDER_RE='<[^>]*>'
unfilled=""
for setting in TOPIC FEATURE_TITLE TECH_DESIGN_PATH USER_STORIES_URL VERTICALE FEATURE_FLAG; do
  if [[ "${!setting}" =~ $PLACEHOLDER_RE ]]; then
    unfilled+=" $setting"
  fi
done
if [[ -n "$unfilled" ]]; then
  echo "Fill in these settings first:$unfilled" >&2
  exit 1
fi

# VERTICALES options, spelled exactly as in the project (#2 has two spaces).
case "$VERTICALE" in
  1) PROJECT_VERTICALE="#1 Actionable & Proactive platform" ;;
  2) PROJECT_VERTICALE="#2  CTI-driven & Full Security Coverage" ;;
  3) PROJECT_VERTICALE="#3 Easy-to-Use & consistent platform" ;;
  *)
    echo "VERTICALE must be 1, 2 or 3, not '$VERTICALE'" >&2
    exit 1
    ;;
esac

# The board sync keeps the issues of a feature-flagged feature open on merge.
case "$FEATURE_FLAG" in
  true)
    EPIC_LABELS+=",feature-flag"
    TASK_LABELS+=",feature-flag"
    ;;
  false) ;;
  *)
    echo "FEATURE_FLAG must be true or false, not '$FEATURE_FLAG'" >&2
    exit 1
    ;;
esac

DRY_RUN=true
if [[ "${1:-}" == "--execute" ]]; then
  DRY_RUN=false
  # Check every issue with a silent dry run first, so nothing is written when one is not ready.
  bash "$0" >/dev/null
fi

WORK_DIR="$(mktemp -d)"
trap 'rm -rf "$WORK_DIR"' EXIT
CREATED=0
UPDATED=0

# Permalink to the last commit on main that changed the tech design: unlike a link to
# main, it survives the brainstorming folder being pruned or moved once the feature ships.
# A re-run links to the latest version.
if ! gh api "repos/${REPO}/contents/${TECH_DESIGN_PATH}?ref=main" --silent 2>/dev/null; then
  echo "${TECH_DESIGN_PATH} is not on main: merge the tech design first" >&2
  exit 1
fi
TECH_DESIGN_SHA="$(gh api "repos/${REPO}/commits?sha=main&path=${TECH_DESIGN_PATH}&per_page=1" -q '.[0].sha')"
TECH_DESIGN_URL="https://github.com/${REPO}/blob/${TECH_DESIGN_SHA}/${TECH_DESIGN_PATH}"

# First line of every issue body.
TECH_DESIGN_LINE="📐 **Tech design**: [tech-design.md](${TECH_DESIGN_URL})"

# =============================================================================
# GitHub helpers
# =============================================================================

find_issue_number() {
  gh issue list -R "$REPO" --state all --search "\"$1\" in:title" --limit 200 \
    --json number,title | jq -r --arg t "$1" 'map(select(.title == $t)) | first | .number // empty'
}

# Resolves once the ids of the issue type and of the project fields.
resolve_ids() {
  ISSUE_TYPE_ID="$(gh api graphql -F owner="$OWNER" -F repo="$REPO_NAME" -f query='
    query($owner: String!, $repo: String!) {
      repository(owner: $owner, name: $repo) { issueTypes(first: 25) { nodes { id name } } }
    }' | jq -r --arg n "$ISSUE_TYPE" '.data.repository.issueTypes.nodes[]? | select(.name == $n) | .id')"

  local project
  project="$(gh api graphql -F owner="$OWNER" -F number="$PROJECT_NUMBER" -f query='
    query($owner: String!, $number: Int!) {
      organization(login: $owner) {
        projectV2(number: $number) {
          id
          fields(first: 50) {
            nodes { ... on ProjectV2SingleSelectField { id name options { id name } } }
          }
        }
      }
    }')"
  PROJECT_ID="$(jq -r '.data.organization.projectV2.id' <<<"$project")"
  STATUS_FIELD_ID="$(jq -r '.data.organization.projectV2.fields.nodes[] | select(.name == "Status") | .id' <<<"$project")"
  STATUS_OPTION_ID="$(jq -r --arg o "$PROJECT_STATUS" '.data.organization.projectV2.fields.nodes[] | select(.name == "Status") | .options[] | select(.name == $o) | .id' <<<"$project")"
  VERTICALE_FIELD_ID="$(jq -r '.data.organization.projectV2.fields.nodes[] | select(.name == "VERTICALES") | .id' <<<"$project")"
  VERTICALE_OPTION_ID="$(jq -r --arg o "$PROJECT_VERTICALE" '.data.organization.projectV2.fields.nodes[] | select(.name == "VERTICALES") | .options[] | select(.name == $o) | .id' <<<"$project")"

  local missing=""
  [[ -n "$ISSUE_TYPE_ID" ]] || missing+=" issue-type:'$ISSUE_TYPE'"
  [[ -n "$PROJECT_ID" && "$PROJECT_ID" != "null" ]] || missing+=" project:#$PROJECT_NUMBER"
  [[ -n "$STATUS_OPTION_ID" ]] || missing+=" status:'$PROJECT_STATUS'"
  [[ -n "$VERTICALE_OPTION_ID" ]] || missing+=" verticale:'$PROJECT_VERTICALE'"
  if [[ -n "$missing" ]]; then
    echo "Cannot resolve on GitHub:$missing" >&2
    exit 1
  fi
}

set_issue_type() {
  gh api graphql -f issueId="$1" -f issueTypeId="$ISSUE_TYPE_ID" -f query='
    mutation($issueId: ID!, $issueTypeId: ID!) {
      updateIssueIssueType(input: { issueId: $issueId, issueTypeId: $issueTypeId }) { issue { id } }
    }' >/dev/null
}

set_project_field() {
  gh api graphql -f projectId="$PROJECT_ID" -f itemId="$1" -f fieldId="$2" -f optionId="$3" -f query='
    mutation($projectId: ID!, $itemId: ID!, $fieldId: ID!, $optionId: String!) {
      updateProjectV2ItemFieldValue(input: {
        projectId: $projectId, itemId: $itemId, fieldId: $fieldId,
        value: { singleSelectOptionId: $optionId }
      }) { projectV2Item { id } }
    }' >/dev/null
}

# Adds the issue to the project, then sets Status and VERTICALES only where they are empty:
# a re-run repairs a run interrupted before the fields were set, and never overwrites a value
# the team has changed since.
add_to_project() {
  local issue_node_id="$1" item item_id
  item="$(gh api graphql -f issueId="$issue_node_id" -f query='
    query($issueId: ID!) {
      node(id: $issueId) {
        ... on Issue {
          projectItems(first: 20) {
            nodes {
              id
              project { id }
              status: fieldValueByName(name: "Status") {
                ... on ProjectV2ItemFieldSingleSelectValue { optionId }
              }
              verticale: fieldValueByName(name: "VERTICALES") {
                ... on ProjectV2ItemFieldSingleSelectValue { optionId }
              }
            }
          }
        }
      }
    }' | jq -c --arg p "$PROJECT_ID" '[.data.node.projectItems.nodes[] | select(.project.id == $p)] | first // empty')"

  if [[ -n "$item" ]]; then
    item_id="$(jq -r '.id' <<<"$item")"
  else
    item='{}'
    item_id="$(gh api graphql -f projectId="$PROJECT_ID" -f contentId="$issue_node_id" \
      -q '.data.addProjectV2ItemById.item.id' -f query='
      mutation($projectId: ID!, $contentId: ID!) {
        addProjectV2ItemById(input: { projectId: $projectId, contentId: $contentId }) { item { id } }
      }')"
  fi

  if [[ -z "$(jq -r '.status.optionId // empty' <<<"$item")" ]]; then
    set_project_field "$item_id" "$STATUS_FIELD_ID" "$STATUS_OPTION_ID"
  fi
  if [[ -z "$(jq -r '.verticale.optionId // empty' <<<"$item")" ]]; then
    set_project_field "$item_id" "$VERTICALE_FIELD_ID" "$VERTICALE_OPTION_ID"
  fi
}

# Makes the issue a sub-issue of the given parent (the epic for a story, the story for a task).
# A task still directly under the epic, as earlier runs left them, is moved under its story; an
# issue someone put under any other parent is left where it is.
link_to_parent() {
  local child_node_id="$1" parent_node_id="$2" parent_label="$3" current replace=false
  if $DRY_RUN; then
    echo "SUB-ISSUE OF: ${parent_label}"
    return
  fi
  current="$(gh api graphql -f issueId="$child_node_id" -q '.data.node.parent.id // empty' -f query='
    query($issueId: ID!) { node(id: $issueId) { ... on Issue { parent { id } } } }')"
  if [[ "$current" == "$parent_node_id" ]]; then
    return
  fi
  if [[ -n "$current" ]]; then
    if [[ "$current" != "$EPIC_NODE_ID" ]]; then
      echo "  ⚠ #${ISSUE_NUMBER} already has another parent issue, not moved under ${parent_label}" >&2
      return
    fi
    replace=true
  fi
  gh api graphql -f parentIssueId="$parent_node_id" -f subIssueId="$child_node_id" \
    -F replaceParent="$replace" -f query='
    mutation($parentIssueId: ID!, $subIssueId: ID!, $replaceParent: Boolean) {
      addSubIssue(input: {
        issueId: $parentIssueId, subIssueId: $subIssueId, replaceParent: $replaceParent
      }) { issue { id } }
    }' >/dev/null
}

# Creates or updates an issue. Sets ISSUE_NUMBER and ISSUE_NODE_ID.
upsert_issue() {
  local title="$1" labels="$2" body_file="$3" existing url
  if [[ "$title" =~ $PLACEHOLDER_RE ]]; then
    echo "Fill in this issue title first: $title" >&2
    exit 1
  fi
  existing="$(find_issue_number "$title")"

  if $DRY_RUN; then
    ISSUE_NUMBER="${existing:-new}"
    ISSUE_NODE_ID=""
    echo ""
    echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
    if [[ -n "$existing" ]]; then
      echo "ACTION: update #${existing}"
      UPDATED=$((UPDATED + 1))
    else
      echo "ACTION: create"
      CREATED=$((CREATED + 1))
    fi
    echo "TITLE:  $title"
    echo "LABELS: $labels"
    echo "BODY:"
    cat "$body_file"
    return
  fi

  if [[ -n "$existing" ]]; then
    gh issue edit "$existing" -R "$REPO" --body-file "$body_file" --add-label "$labels" >/dev/null
    ISSUE_NUMBER="$existing"
    UPDATED=$((UPDATED + 1))
    echo "updated #${ISSUE_NUMBER}  $title"
  else
    url="$(gh issue create -R "$REPO" --title "$title" --label "$labels" --body-file "$body_file")"
    ISSUE_NUMBER="${url##*/}"
    CREATED=$((CREATED + 1))
    echo "created #${ISSUE_NUMBER}  $title"
  fi
  ISSUE_NODE_ID="$(gh issue view "$ISSUE_NUMBER" -R "$REPO" --json id -q .id)"
  set_issue_type "$ISSUE_NODE_ID"
  add_to_project "$ISSUE_NODE_ID"
}

# Writes stdin to a body file, after the tech design link and an optional extra line.
# Prints the file path.
write_body() {
  local extra_line="${1:-}" body_file
  body_file="$(mktemp "$WORK_DIR/body.XXXXXX")"
  {
    echo "$TECH_DESIGN_LINE"
    if [[ -n "$extra_line" ]]; then
      echo "$extra_line"
    fi
    echo ""
    cat
  } >"$body_file"
  echo "$body_file"
}

# Usage: epic <<'BODY' ... BODY
epic() {
  local user_stories_line=""
  if [[ -n "$USER_STORIES_URL" ]]; then
    user_stories_line="📋 **User stories**: [Notion](${USER_STORIES_URL})"
  fi
  upsert_issue "feat(${TOPIC}): epic for ${FEATURE_TITLE}" "$EPIC_LABELS" "$(write_body "$user_stories_line")"
  EPIC_NUMBER="$ISSUE_NUMBER"
  EPIC_NODE_ID="$ISSUE_NODE_ID"
}

# Usage: story "US1 <title>" <<'BODY' ... BODY
# A sub-issue of the epic. The tasks that follow it go under it, so it shows their progress.
story() {
  upsert_issue "feat(${TOPIC}): $1" "$TASK_LABELS" "$(write_body)"
  link_to_parent "$ISSUE_NODE_ID" "$EPIC_NODE_ID" "epic #${EPIC_NUMBER}"
  STORY_ID="${1%% *}"
  STORY_NUMBER="$ISSUE_NUMBER"
  STORY_NODE_ID="$ISSUE_NODE_ID"
}

# Usage: task "US1.1 <title>" <<'BODY' ... BODY
# A sub-issue of the story declared just before it (US1.1 goes under US1).
task() {
  if [[ -z "${STORY_ID:-}" || "${1%% *}" != "${STORY_ID}".* ]]; then
    echo "Task '$1' must come right after its story: story \"${1%%.*} …\"" >&2
    exit 1
  fi
  upsert_issue "feat(${TOPIC}): $1" "$TASK_LABELS" "$(write_body)"
  link_to_parent "$ISSUE_NODE_ID" "$STORY_NODE_ID" "${STORY_ID} #${STORY_NUMBER}"
}

# Read-only: the dry run also checks that the project, status and vertical exist.
resolve_ids

# =============================================================================
# Issues
#
# Bodies are quoted heredocs (<<'BODY'): backticks, $ and Mermaid arrows are
# kept verbatim. Keep titles stable: the title is how a re-run finds an issue.
# =============================================================================

epic <<'BODY'
## Context

<What the feature brings and why, in a few sentences, from the user stories and the tech design.>

## User stories

- US1 — <story title>
- US2 — <story title>
BODY

# --- US1 ---------------------------------------------------------------------

story "US1 <story title>" <<'BODY'
## User story

As a <persona>, I want <goal> so that <benefit>.

## Acceptance criteria

- [ ] <AC copied from user-stories.md, every one of them>

## UX

<Figma links and images from the user stories, if any.>
BODY

task "US1.1 <task title>" <<'BODY'
## Context

<What this task delivers for US1. Excerpt of the tech design, optionally a Mermaid diagram.>

```mermaid
sequenceDiagram
  <only the part of the tech design this task implements>
```

## Definition of Done

- [ ] <functional outcome, checkable by the PR reviewer>
- [ ] Unit tests cover <behaviour>
- [ ] <how to check it works: endpoint, screen or scenario to try>
BODY

echo ""
if $DRY_RUN; then
  echo "Dry run: ${CREATED} to create, ${UPDATED} to update. Use --execute to apply."
else
  echo "Done: ${CREATED} created, ${UPDATED} updated. Epic: https://github.com/${REPO}/issues/${EPIC_NUMBER}"
fi
